package salesforce

import (
	"encoding/xml"
	"fmt"
	"path"
	"slices"
	"strconv"
	"strings"

	"github.com/unstoppablemango/tdl/backend/internal/emit"
	"github.com/unstoppablemango/tdl/ir"
	"github.com/unstoppablemango/tdl/plugin"
)

const metadataNS = "http://soap.sforce.com/2006/04/metadata"

// header opens every XML file this backend writes.
const header = xml.Header + "<!-- Code generated by tdl. DO NOT EDIT. -->\n"

// The elements below are in the order a retrieve from an org writes them,
// so a generated file and a retrieved one diff cleanly.

type customObject struct {
	XMLName          xml.Name  `xml:"CustomObject"`
	NS               string    `xml:"xmlns,attr"`
	DeploymentStatus string    `xml:"deploymentStatus"`
	Description      string    `xml:"description,omitempty"`
	Label            string    `xml:"label"`
	NameField        nameField `xml:"nameField"`
	PluralLabel      string    `xml:"pluralLabel"`
	SharingModel     string    `xml:"sharingModel"`
}

type nameField struct {
	DisplayFormat string `xml:"displayFormat"`
	Label         string `xml:"label"`
	Type          string `xml:"type"`
}

type customField struct {
	XMLName           xml.Name  `xml:"CustomField"`
	NS                string    `xml:"xmlns,attr"`
	FullName          string    `xml:"fullName"`
	DefaultValue      string    `xml:"defaultValue,omitempty"`
	DeleteConstraint  string    `xml:"deleteConstraint,omitempty"`
	Description       string    `xml:"description,omitempty"`
	ExternalID        bool      `xml:"externalId,omitempty"`
	Label             string    `xml:"label"`
	Length            int       `xml:"length,omitempty"`
	Precision         int       `xml:"precision,omitempty"`
	ReferenceTo       string    `xml:"referenceTo,omitempty"`
	RelationshipLabel string    `xml:"relationshipLabel,omitempty"`
	RelationshipName  string    `xml:"relationshipName,omitempty"`
	Required          bool      `xml:"required,omitempty"`
	Scale             *int      `xml:"scale,omitempty"`
	Type              string    `xml:"type"`
	Unique            bool      `xml:"unique,omitempty"`
	ValueSet          *valueSet `xml:"valueSet,omitempty"`
	VisibleLines      int       `xml:"visibleLines,omitempty"`
}

type valueSet struct {
	Restricted bool          `xml:"restricted"`
	Definition valueSetValue `xml:"valueSetDefinition"`
}

type valueSetValue struct {
	Sorted bool          `xml:"sorted"`
	Values []customValue `xml:"value"`
}

type customValue struct {
	FullName string `xml:"fullName"`
	Default  bool   `xml:"default"`
	Label    string `xml:"label"`
}

// column is how a TDL primitive is stored: a field type and, for the ones
// that have them, a length or a precision and scale.
type column struct {
	typ              string
	length           int
	precision, scale int
}

// columns maps a TDL primitive to the field type holding it. A Number holds
// 18 digits, which is every int an org stores. An org has no duration, so
// one is ISO 8601 text, and no binary field, so bytes has no entry.
var columns = map[string]column{
	"string":   {typ: "Text", length: 255},
	"int":      {typ: "Number", precision: 18},
	"bool":     {typ: "Checkbox"},
	"decimal":  {typ: "Number", precision: 18, scale: 6},
	"uuid":     {typ: "Text", length: 36},
	"instant":  {typ: "DateTime"},
	"date":     {typ: "Date"},
	"duration": {typ: "Text", length: 64},
}

// objectName is an entity's API name.
func (g *generator) objectName(d *ir.Decl) string {
	return g.DeclName(d, emit.Pascal) + "__c"
}

// object renders an entity as a custom object and a file per field it can
// store.
//
// A field with no column is skipped with a warning and the object is still
// written. The schema backends skip a whole declaration instead, because a
// struct missing a field is a different type, and an object missing a
// column still deploys.
func (g *generator) object(d *ir.Decl) ([]*plugin.File, error) {
	pos := d.GetMeta().GetPosition()
	name := d.GetMeta().GetName()
	base := g.DeclName(d, emit.Pascal)
	if err := checkName(pos, name, base); err != nil {
		return nil, err
	}
	api := base + "__c"
	if err := claim(g.objects, pos, name, api); err != nil {
		return nil, err
	}

	lbl := label(base)
	if s, ok := g.Text(d.GetDirectives(), "label"); ok {
		lbl = s
	}
	plural := lbl + "s"
	if s, ok := g.Text(d.GetDirectives(), "plural"); ok {
		plural = s
	}

	key := g.key(d)
	dir := path.Join("objects", api)
	seen := map[string]bool{}
	var files []*plugin.File
	for _, f := range d.Fields() {
		fld, err := g.field(base, f)
		if err != nil {
			g.Warn(err)
			continue
		}
		lower := strings.ToLower(fld.FullName)
		if seen[lower] {
			return nil, emit.Unsupported(f.GetMeta().GetPosition(), "%s has two fields named %s in Salesforce", name, fld.FullName)
		}
		seen[lower] = true
		if f == key {
			switch fld.Type {
			case "Text", "Number":
				fld.ExternalID, fld.Unique = true, true
			default:
				g.Warn(emit.Unsupported(f.GetMeta().GetPosition(),
					"%s is keyed by %s, and a %s field cannot be an external ID", name, f.GetMeta().GetName(), fld.Type))
			}
		}
		files = append(files, xmlFile(path.Join(dir, "fields", fld.FullName+".field-meta.xml"), fld))
	}

	obj := &customObject{
		NS:               metadataNS,
		DeploymentStatus: "Deployed",
		Description:      description(d.GetMeta()),
		Label:            lbl,
		NameField: nameField{
			DisplayFormat: base + "-{0000}",
			Label:         lbl + " Number",
			Type:          "AutoNumber",
		},
		PluralLabel:  plural,
		SharingModel: "ReadWrite",
	}
	objFile := xmlFile(path.Join(dir, api+".object-meta.xml"), obj)
	return append([]*plugin.File{objFile}, files...), nil
}

// key returns the field a `key` directive names, or nil when there is none
// or it names something an external ID cannot be, which it warns about.
func (g *generator) key(d *ir.Decl) *ir.Field {
	dir, ok := g.Find(d.GetDirectives(), "key")
	if !ok {
		return nil
	}
	name := d.GetMeta().GetName()
	if len(dir.GetArgs()) > 1 {
		g.Warn(emit.Unsupported(dir.GetPosition(),
			"%s has a key of %d fields, and a Salesforce external ID is one field", name, len(dir.GetArgs())))
		return nil
	}
	arg := dir.GetArgs()[0]
	if arg.GetKind() != ir.LiteralKind_LITERAL_KIND_NAME {
		g.Warn(emit.Unsupported(dir.GetPosition(), "a key names a field, and %q is %s", arg.GetText(), ir.KindName(arg.GetKind())))
		return nil
	}
	i := slices.IndexFunc(d.Fields(), func(f *ir.Field) bool { return f.GetMeta().GetName() == arg.GetText() })
	if i < 0 {
		g.Warn(emit.Unsupported(dir.GetPosition(), "%s is keyed by %s, which is not one of its fields", name, arg.GetText()))
		return nil
	}
	return d.Fields()[i]
}

// field renders one field of an object, or says why it has no column.
func (g *generator) field(object string, f *ir.Field) (*customField, error) {
	pos := f.GetMeta().GetPosition()
	what := object + "." + f.GetMeta().GetName()
	base := g.FieldName(f, emit.Pascal)
	if err := checkName(pos, what, base); err != nil {
		return nil, err
	}

	ref, err := g.Resolve(f.GetType())
	if err != nil {
		return nil, err
	}
	required := true
	for ref.Form == emit.Option || ref.Form == emit.Nullable {
		required = false
		ref = ref.Elem
	}
	if ref, err = g.Expand(ref); err != nil {
		return nil, err
	}

	fld := &customField{
		NS:          metadataNS,
		FullName:    base + "__c",
		Description: description(f.GetMeta()),
		Label:       label(base),
		Required:    required,
	}
	if s, ok := g.Text(f.GetDirectives(), "label"); ok {
		fld.Label = s
	}

	switch {
	case ref.Form == emit.Prim:
		col, ok := columns[ref.Name]
		if !ok {
			return nil, emit.Unsupported(pos, "%s is %s, which no Salesforce field type holds", what, ref.Name)
		}
		fld.Type, fld.Length, fld.Precision = col.typ, col.length, col.precision
		if col.typ == "Number" {
			scale := col.scale
			fld.Scale = &scale
		}
		if col.typ == "Checkbox" {
			// A checkbox is never empty, so it cannot be required and has
			// to start somewhere.
			fld.Required, fld.DefaultValue = false, "false"
		}
		if err := g.sizes(f, fld, ref.Name); err != nil {
			return nil, err
		}

	case ref.Form == emit.Named && ref.Decl.GetStructure().GetKind() == ir.StructKind_STRUCT_KIND_ENTITY:
		fld.Type = "Lookup"
		fld.ReferenceTo = g.objectName(ref.Decl)
		fld.RelationshipName = object + base
		fld.RelationshipLabel = label(object) + " " + fld.Label
		// A required lookup cannot clear itself when its target is
		// deleted, so it refuses the delete instead.
		fld.DeleteConstraint = "SetNull"
		if required {
			fld.DeleteConstraint = "Restrict"
		}

	case ref.Form == emit.Named && picklist(ref.Decl):
		fld.Type = "Picklist"
		fld.ValueSet = g.values(ref.Decl)

	case ref.Form == emit.Set:
		elem, err := g.Expand(ref.Elem)
		if err != nil {
			return nil, err
		}
		if elem.Form != emit.Named || !picklist(elem.Decl) {
			return nil, emit.Unsupported(pos, "%s is a set of something other than a fieldless enum, which no Salesforce field type holds", what)
		}
		// An empty set is a value, so a multi-select is never required.
		fld.Type, fld.Required, fld.VisibleLines = "MultiselectPicklist", false, 4
		fld.ValueSet = g.values(elem.Decl)

	default:
		return nil, emit.Unsupported(pos, "%s has no Salesforce field type, and the object is written without it", what)
	}
	return fld, nil
}

// sizes applies a field's `length` and `scale` directives.
func (g *generator) sizes(f *ir.Field, fld *customField, prim string) error {
	pos := f.GetMeta().GetPosition()
	if s, ok := g.Text(f.GetDirectives(), "length"); ok {
		n, err := strconv.Atoi(s)
		if err != nil || fld.Type != "Text" || n < 1 || n > 255 {
			return emit.Unsupported(pos, "length(%s) sets the length of a Text field, from 1 to 255", s)
		}
		fld.Length = n
	}
	if s, ok := g.Text(f.GetDirectives(), "scale"); ok {
		n, err := strconv.Atoi(s)
		if err != nil || prim != "decimal" || n < 0 || n > fld.Precision {
			return emit.Unsupported(pos, "scale(%s) sets the decimal places of a decimal field, from 0 to %d", s, columns["decimal"].precision)
		}
		fld.Scale = &n
	}
	return nil
}

func picklist(d *ir.Decl) bool {
	e := d.GetEnumeration()
	return e != nil && !emit.Fielded(e)
}

// values is an enum's variants as a restricted picklist's values, so the
// org refuses anything the enum does not name.
func (g *generator) values(d *ir.Decl) *valueSet {
	set := &valueSet{Restricted: true}
	for _, v := range d.GetEnumeration().GetVariants() {
		n := v.GetMeta().GetName()
		set.Definition.Values = append(set.Definition.Values, customValue{FullName: n, Label: label(n)})
	}
	return set
}

func xmlFile(p string, v any) *plugin.File {
	out, err := xml.MarshalIndent(v, "", "    ")
	if err != nil {
		// Every value marshalled here is a struct of strings, ints, and
		// bools, which cannot fail.
		panic(fmt.Sprintf("marshal %s: %v", p, err))
	}
	return &plugin.File{Path: p, Content: []byte(header + string(out) + "\n")}
}
